(function(){'use strict';const p=new URLSearchParams(location.search),cfg=window.EmbeddedMiniConfig||{key:p.get('game'),token:p.get('token'),pink:p.get('pink')==='1',readonly:p.get('album')==='1'},key=cfg.key;if(!key)return;const mapping={'mini-basket':['basket','basket'],'mini-photo':['camera','photo'],'mini-badminton':['arcade','badminton'],'mini-runner':['arcade','runner'],'mini-claw':['arcade','claw'],'mini-squish':['arcade','squish'],'mini-pinball':['arcade','pinball']},route=mapping[key];if(!route)return;let sent=false;const send=score=>{if(sent||cfg.readonly)return;sent=true;parent.postMessage({type:'naiwa-mini-result',key,token:cfg.token,score},location.origin==='null'?'*':location.origin);};
const style=document.createElement('style');style.textContent='.top,.tabs,.arcade-picker,footer,.preview-tag,.bottom-note,#mini-reset,#prize-shelf{display:none!important}.shell{max-width:1000px;padding:0 16px}.section-head{margin:16px 0}.section-head h1{font-size:24px}.arcade-layout{gap:18px}.mini-overlay h2{font-size:20px}.view{padding-bottom:12px}.section-head .description{font-size:12px}.mini-finish{display:block;margin:20px auto;background:#688052;border:0;border-radius:12px;padding:14px 25px;color:#fff;cursor:pointer}';document.head.append(style);
if(route[0]==='arcade'){document.querySelector('#arcade-view .section-head').hidden=true;}window.PreviewNavigate(cfg.readonly?'album':route[0]);if(route[0]==='arcade')window.PreviewSelectMini(route[1]);if(cfg.readonly){document.querySelector('[data-open-camera]').hidden=true;const back=document.querySelector('#keep-shooting');back.textContent='回到相册';back.onclick=()=>document.querySelector('#photo-dialog').close();}if(!cfg.pink)document.querySelector('[data-scene="together"]')?.remove();
let pendingScore=0;window.addEventListener('mini:result',e=>{if(e.detail?.kind!==route[1])return;pendingScore=e.detail.score;parent.postMessage({type:'naiwa-mini-ready',key,token:cfg.token,score:pendingScore},location.origin==='null'?'*':location.origin);if(route[1]==='photo')return;setTimeout(()=>{const host=document.querySelector(route[0]==='basket'?'#basket-overlay .overlay-card':'#mini-overlay .mini-card');if(!host)return;host.querySelectorAll('button').forEach(b=>b.remove());const done=document.createElement('button');done.className='button green';done.textContent='收下成绩，回校园';done.onclick=()=>send(pendingScore);host.append(done);},0);});
if(route[1]==='photo'&&!cfg.readonly){const done=document.querySelector('#keep-shooting');done.textContent='收好照片，回校园';done.onclick=()=>send(pendingScore);}
if(route[1]==='squish'){const button=document.createElement('button');button.textContent='玩好了，回校园';button.className='mini-finish';button.onclick=()=>send(0);document.querySelector('#arcade-view').append(button);}
})();
